#!/usr/bin/env node

import { spawn } from 'child_process';
import { setTimeout } from 'timers/promises';
import { config } from '../src/config/index.js';

// 颜色输出
const colors = {
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  reset: '\x1b[0m'
};

function log(color, message) {
  console.log(`${color}${message}${colors.reset}`);
}

async function testHealth(endpoint) {
  try {
    const response = await fetch(`${endpoint}/health`);
    const data = await response.json();
    return response.ok && data.status === 'ok';
  } catch (error) {
    return false;
  }
}

async function testTools(endpoint) {
  try {
    const response = await fetch(`${endpoint}/tools`);
    const data = await response.json();
    return response.ok && data.tools && data.tools.length > 0;
  } catch (error) {
    return false;
  }
}

async function testTransport(mode, port = null) {
  log(colors.blue, `\n🧪 Testing ${mode.toUpperCase()} transport...`);
  
  const args = ['src/index.js', '--transport', mode];
  if (port) {
    args.push('--port', port.toString());
  }
  
  const server = spawn('node', args, {
    stdio: mode === 'stdio' ? 'pipe' : 'ignore',
    env: { ...process.env, GET_NOTE_API_KEY: 'test-key' }
  });
  
  let testPassed = false;
  
  try {
    // 等待服务器启动
    await setTimeout(2000);
    
    if (mode === 'stdio') {
      // STDIO模式测试
      const result = await new Promise((resolve) => {
        let output = '';
        server.stdout.on('data', (data) => {
          output += data.toString();
        });
        
        // 发送健康检查请求
        server.stdin.write('{"jsonrpc":"2.0","method":"mcp.listTools","id":1}\n');
        
        setTimeout(1000).then(() => {
          resolve(output.includes('search_knowledge'));
        });
      });
      
      testPassed = result;
    } else {
      // HTTP/SSE模式测试
      const endpoint = `http://localhost:${port}`;
      const healthOk = await testHealth(endpoint);
      const toolsOk = await testTools(endpoint);
      testPassed = healthOk && toolsOk;
      
      if (healthOk) log(colors.green, '✅ Health check passed');
      else log(colors.red, '❌ Health check failed');
      
      if (toolsOk) log(colors.green, '✅ Tools endpoint working');
      else log(colors.red, '❌ Tools endpoint failed');
    }
    
  } catch (error) {
    log(colors.red, `❌ ${mode} test error: ${error.message}`);
  } finally {
    // 清理进程
    server.kill('SIGTERM');
    await setTimeout(1000);
  }
  
  if (testPassed) {
    log(colors.green, `✅ ${mode.toUpperCase()} transport test PASSED`);
  } else {
    log(colors.red, `❌ ${mode.toUpperCase()} transport test FAILED`);
  }
  
  return testPassed;
}

async function main() {
  log(colors.blue, '🚀 Starting comprehensive MCP server tests...\n');
  
  // 检查API密钥
  if (!process.env.GET_NOTE_API_KEY) {
    log(colors.yellow, '⚠️  GET_NOTE_API_KEY not set, using test mode');
    process.env.GET_NOTE_API_KEY = 'test-key';
  }
  
  const results = {};
  
  // 测试所有传输模式
  results.stdio = await testTransport('stdio');
  results.sse = await testTransport('sse', 3001);
  results.http = await testTransport('http', 3002);
  
  // 总结结果
  log(colors.blue, '\n📊 Test Summary:');
  log(colors.blue, '================');
  
  Object.entries(results).forEach(([mode, passed]) => {
    const color = passed ? colors.green : colors.red;
    const status = passed ? 'PASSED' : 'FAILED';
    log(color, `${mode.toUpperCase()}: ${status}`);
  });
  
  const allPassed = Object.values(results).every(result => result);
  
  if (allPassed) {
    log(colors.green, '\n🎉 All tests PASSED! Server is ready to use.');
    log(colors.blue, '\n📋 Next steps:');
    log(colors.blue, '1. Set your real API key: export GET_NOTE_API_KEY="your-key"');
    log(colors.blue, '2. Choose a transport mode and start the server');
    log(colors.blue, '3. Test with MCP Inspector: npm run inspector');
  } else {
    log(colors.red, '\n❌ Some tests FAILED. Please check the errors above.');
    process.exit(1);
  }
}

// 运行测试
main().catch(error => {
  console.error('Test runner error:', error);
  process.exit(1);
});